INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('covered-length', 7, NULL, 'def gen():
    _s = [200849002]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    M = 1000000000
    L = 10000000
    N = 200000
    lines = []
    for _ in range(N):
        l = r(0, M - 1)
        rr = min(M, l + r(1, L))
        lines.append(f"{l} {rr}")
    return f"{N}\n" + "\n".join(lines) + "\n"
', '999992148', 0);
